package chihalu.customstacklimit.command;

import chihalu.customstacklimit.StackLimitConfig;
import com.mojang.brigadier.CommandDispatcher;
import com.mojang.brigadier.arguments.IntegerArgumentType;
import com.mojang.brigadier.context.CommandContext;
import com.mojang.brigadier.exceptions.CommandSyntaxException;
import net.minecraft.command.CommandRegistryAccess;
import net.minecraft.server.command.CommandManager;
import net.minecraft.server.command.ServerCommandSource;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.text.Text;

/**
 * /stack コマンドの実装
 */
public class StackCommand {
    
    public static void register(CommandDispatcher<ServerCommandSource> dispatcher, CommandRegistryAccess registryAccess, CommandManager.RegistrationEnvironment environment) {
        dispatcher.register(CommandManager.literal("stack")
            .then(CommandManager.argument("count", IntegerArgumentType.integer(1, 32767))
                .executes(StackCommand::setStackLimit))
            .executes(StackCommand::showCurrentStackLimit));
    }

    /**
     * スタック数を設定する
     */
    private static int setStackLimit(CommandContext<ServerCommandSource> context) throws CommandSyntaxException {
        ServerPlayerEntity player = context.getSource().getPlayerOrThrow();
        int stackLimit = IntegerArgumentType.getInteger(context, "count");
        
        // プレイヤーのスタック数を設定
        StackLimitConfig.setPlayerStackLimit(player.getUuid(), stackLimit);
        
        // 成功メッセージを表示
        context.getSource().sendFeedback(
            () -> Text.literal("§aアイテムのスタック数を " + stackLimit + " 個に設定しました！"),
            false
        );
        
        // インベントリを更新（既存のアイテムスタックを再計算）
        player.getInventory().markDirty();
        player.currentScreenHandler.syncState();
        
        return 1;
    }

    /**
     * 現在のスタック数設定を表示する
     */
    private static int showCurrentStackLimit(CommandContext<ServerCommandSource> context) throws CommandSyntaxException {
        ServerPlayerEntity player = context.getSource().getPlayerOrThrow();
        int currentLimit = StackLimitConfig.getPlayerStackLimit(player.getUuid());
        
        context.getSource().sendFeedback(
            () -> Text.literal("§e現在のスタック数: " + currentLimit + " 個"),
            false
        );
        
        return 1;
    }
}
